const fs = require("fs");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
(async () => {
  let tw, css;
  try {
    tw = require("tailwindcss");
    css = fs.readFileSync("/w/node_modules/tailwindcss/index.css", "utf8");
  } catch (e) { broken("cannot load tailwindcss: " + e.message); }
  const ds = await tw.__unstable__loadDesignSystem(css, { base: "/tmp" });
  if (typeof ds.canonicalizeCandidates !== "function") broken("canonicalizeCandidates is missing");
  const css1 = ds.candidatesToCss(["start-full", "inset-s-full"]);
  if (!css1[0] || !css1[1]) broken("start-full or inset-s-full does not generate CSS");
  const same = ds.canonicalizeCandidates(["inset-s-full"]);
  if (same.length !== 1 || same[0] !== "inset-s-full") broken("inset-s-full canonicalized to " + JSON.stringify(same));
  const a = ds.canonicalizeCandidates(["start-full"]);
  const b = ds.canonicalizeCandidates(["-start-full"]);
  console.log(JSON.stringify([a, b]));
  if (a.join() === "start-full" && b.join() === "-start-full") symptom("canonicalizeCandidates keeps start-full and -start-full unchanged");
  if (a.join() !== "inset-s-full" || b.join() !== "-inset-s-full") broken("unexpected result " + JSON.stringify([a, b]));
  console.log("OK: start-full and -start-full canonicalize to inset-s-full and -inset-s-full");
})().catch(e => broken(String((e && e.stack) || e)));

